def lines_edit(p, repl, append=None):
    L = open(p, encoding="utf-8").read().split("\n"); hit = set()
    for i, l in enumerate(L):
        for k, v in repl.items():
            if l.startswith(k):
                L[i] = v if v is not None else L[i]; hit.add(k)
    miss = set(repl) - hit; assert not miss, (p, miss)
    s = "\n".join(L)
    if append: s = s.rstrip("\n") + "\n" + append + "\n"
    open(p, "w", encoding="utf-8", newline="\n").write(s)

